import json
import re

REQUIRED_MEALS = ["MORNING", "BREAKFAST", "LUNCH", "DINNER"]


def normalize_day_no(day_no, fallback):
    """把各种 day_no 写法规范化为整数"""
    if isinstance(day_no, int):
        return day_no
    if isinstance(day_no, float):
        return int(day_no)
    try:
        return int(str(day_no).strip())
    except (TypeError, ValueError):
        pass
    m = re.search(r"\d+", str(day_no))
    if m:
        return int(m.group())
    return fallback


def parse_day_recipe_json(raw):
    """清洗并解析 LLM 输出的 day_recipe_json，兼容 Markdown 围栏和多余文本"""
    if not isinstance(raw, str):
        return raw
    text = raw.strip()
    if text.startswith("```"):
        text = text.strip("`")
        if text.lower().startswith("json"):
            text = text[4:]
        text = text.strip()
    start = text.find("{")
    end = text.rfind("}")
    if start >= 0 and end > start:
        text = text[start:end + 1]
    try:
        return json.loads(text)
    except Exception:
        # 尝试修复被截断的 JSON
        fixed = fix_truncated_recipe_json(text)
        if fixed is not None:
            return fixed
        raise


def fix_truncated_recipe_json(text):
    """修复 LLM 输出的被截断食谱 JSON"""
    text = text.strip()

    # 场景 1：截断在 DINNER 字段或更后面，已有完整 MORNING/BREAKFAST/LUNCH/DINNER
    dinner_match = re.search(r'"DINNER"\s*:\s*"([^"]*)"', text)
    if dinner_match:
        dinner_end = dinner_match.end()
        fixed = text[:dinner_end] + ', "usedIngredients": [], "adjustmentNotes": []}'
        try:
            return json.loads(fixed)
        except Exception:
            pass

    # 场景 2：截断在某个字符串值中间，尝试用更通用的方式补全 meals 后结构
    last_match = None
    for pattern in [r'"([A-Z]+)"\s*:\s*"([^"]*)"', r'"([A-Z]+)"\s*:\s*\[([^\]]*)\]']:
        for m in re.finditer(pattern, text):
            last_match = m
    if last_match and last_match.end() < len(text):
        fixed = text[:last_match.end()] + ', "usedIngredients": [], "adjustmentNotes": []}'
        try:
            return json.loads(fixed)
        except Exception:
            pass

    return None


def extract_raw_from_item(item):
    """从上游 item 中提取食谱 raw，兼容包装结构和直接对象"""
    if not isinstance(item, dict):
        return item
    # 如果 item 本身就是食谱对象（包含 meals），直接返回
    if "meals" in item:
        return item
    # 优先取 day_recipe_json（JSON 字符串）
    if item.get("day_recipe_json") not in (None, ""):
        return item.get("day_recipe_json")
    # 尝试其他常见字段
    for key in ["output", "result", "content", "data"]:
        if item.get(key) not in (None, ""):
            return item.get(key)
    return None


async def main(args: Args) -> Output:
    params = args.params
    output_list = params.get("outputList") or []

    debug_logs = []

    def log(step, info):
        debug_logs.append({"step": step, "info": info})

    log("input_type", {"output_list_type": type(output_list).__name__, "is_list": isinstance(output_list, list)})

    # 兼容：参数声明为 string 时，Coze 会把上游 list 序列化为 JSON 字符串传入
    if isinstance(output_list, str):
        log("input_is_string", {"length": len(output_list), "preview": output_list[:200]})
        try:
            output_list = json.loads(output_list)
            log("parsed_string", {"parsed_type": type(output_list).__name__})
        except Exception as exc:
            log("parse_string_error", {"error": str(exc)})
            output_list = []
    if not isinstance(output_list, list):
        log("input_not_list", {"type": type(output_list).__name__})
        output_list = []

    valid_days = []
    failed_days = []
    errors = []

    for index, item in enumerate(output_list):
        item_type = type(item).__name__
        item_keys = list(item.keys()) if isinstance(item, dict) else None
        log(f"item_{index}_start", {"item_type": item_type, "item_keys": item_keys})

        raw = extract_raw_from_item(item)
        raw_type = type(raw).__name__
        raw_preview = str(raw)[:300]
        log(f"item_{index}_raw", {"raw_type": raw_type, "raw_preview": raw_preview})

        if raw in (None, "", {}):
            failed_days.append(index + 1)
            err = {
                "index": index + 1,
                "error": "day_recipe_json 为空",
                "item_type": item_type,
                "item_keys": item_keys,
            }
            errors.append(err)
            log(f"item_{index}_empty", err)
            continue

        try:
            obj = parse_day_recipe_json(raw)
            log(f"item_{index}_parsed", {"obj_type": type(obj).__name__, "keys": list(obj.keys())[:20] if isinstance(obj, dict) else None})

            if not isinstance(obj, dict):
                raise ValueError("不是有效的 JSON 对象，类型：" + type(obj).__name__)

            # 加固1：检测兜底/失败标记，防止"假成功"（dataOnErr 兜底或模型输出失败文案）
            raw_text = str(raw)
            if any(mark in raw_text for mark in ["生成失败", "请重新生成", "默认兜底"]):
                raise ValueError("检测到兜底/失败标记，视为生成失败")

            # 加固2：item 自带 isSuccess=false 时判失败
            if isinstance(item, dict) and item.get("isSuccess") is False:
                raise ValueError("批处理项 isSuccess=false")

            # 加固3：强制使用批处理顺序编号，不信 LLM 输出的 day_no（防幻觉/兜底错号）
            day_no = index + 1
            obj["day_no"] = day_no

            day_label = obj.get("dayLabel") or obj.get("day_label") or ""
            # 优先用数据库记录的 day_label，保证与 day_no 对齐
            base_label = item.get("day_label") if isinstance(item, dict) else None
            if base_label:
                day_label = base_label
            else:
                m = re.search(r"\d+", str(day_label))
                if m and int(m.group()) != day_no:
                    day_label = f"Day{day_no}"
            obj["dayLabel"] = day_label

            meals = obj.get("meals") or {}
            log(f"item_{index}_meals", {"meals_type": type(meals).__name__, "meals_keys": list(meals.keys()) if isinstance(meals, dict) else None})

            missing = [k for k in REQUIRED_MEALS if k not in meals]
            if missing:
                raise ValueError("缺少餐次：" + ",".join(missing))
            if not meals.get("BREAKFAST") or not meals.get("LUNCH") or not meals.get("DINNER"):
                raise ValueError("早餐、午餐或晚餐为空")

            valid_days.append(obj)
            log(f"item_{index}_success", {"day_no": day_no, "day_label": day_label})
        except Exception as exc:
            failed_days.append(index + 1)
            err = {
                "index": index + 1,
                "error": str(exc),
                "item_type": item_type,
                "raw_type": raw_type,
                "raw_preview": raw_preview,
            }
            errors.append(err)
            log(f"item_{index}_error", err)

    ok = (len(valid_days) == 28) and (not failed_days)
    status = "SUCCESS" if ok else "FAILED"
    result = {
        "status": status,
        "is_success": ok,
        "valid_days": {"items": valid_days},
        "failed_days": ",".join(str(x) for x in failed_days),
        "errors": {"items": errors},
        "completed_days": str(len(valid_days)),
        "total_days": "28",
        "debug_logs": {"items": debug_logs}
    }
    log("final_result", {"completed_days": len(valid_days), "failed_count": len(failed_days)})
    return result
